def preserve_orders(apps, schema_editor):
    Order = apps.get_model('tienda', 'Orden')
    orders = Order.objects.using(schema_editor.connection.alias)
    # Old finalizado was the terminal fulfilment state, independently of pagado.
    # No dispatch/delivery timestamp existed: leave those unknown, never fabricate them.
    orders.filter(estado='finalizado').update(estado='entregado', finalizado_historico=True)
    orders.filter(pagado=True).update(pago_origen='historico')
    # Old code attempted initial mail at checkout, or after MP approval. Its
    # delivery cannot be proven. Suppress retrospective mail for those records.
    orders.exclude(metodo_pago='mercadopago', pagado=False).update(emails_iniciales_preexistentes=True)
    for pk in orders.values_list('pk', flat=True).iterator():
        orders.filter(pk=pk).update(seguimiento_token=uuid.uuid4())


def restore_states(apps, schema_editor):
    orders = apps.get_model('tienda', 'Orden').objects.using(schema_editor.connection.alias)
    orders.filter(estado='entregado').update(estado='finalizado')
    orders.filter(estado__in=['confirmado', 'en_envio']).update(estado='en_proceso')


